update public.spell_catalog set name_ru='Газообразная форма', casting_time='Действие', spell_range='Касание', area='1 добровольное существо', duration='Концентрация, до 1 часа', components=array['В','С','М'], material='кусочек марли', check_type='', damage='', effect_summary='Цель вместе с надетыми и переносимыми предметами превращается в облако тумана. Получает скорость полёта 10 футов и зависание, сопротивление дробящему, колющему и рубящему урону, иммунитет к Сбит с ног и преимущество на спасброски Силы, Ловкости и Телосложения. Может проходить через узкие щели и занимать пространство других существ.', upcast='+1 цель за каждый уровень ячейки выше 3.', notes='Жидкости считаются твёрдой поверхностью. Цель не может говорить, манипулировать предметами, атаковать или накладывать заклинания. Эффект заканчивается при 0 HP или если цель действием Магии прекращает его.', author_description='Превращаешь союзника в облако, чтобы двери, клетки и большая часть оружия внезапно стали рекомендациями. Разговоры, правда, тоже становятся невозможны. Иногда это бонус.', author_comment='Если бард добровольно согласился стать туманом, пользуйся моментом: целый час тишины.' where slug='gaseous-form';
update public.spell_catalog set name_ru='Охранная руна', casting_time='Действие', spell_range='Касание', area='Поверхность или закрываемый объект; взрыв — сфера радиусом 20 футов', duration='До рассеивания или срабатывания', components=array['В','С','М'], material='алмазная пыль стоимостью 200+ зм, расходуется', check_type='Обнаружение: Мудрость (Восприятие) против Сл спасброска заклинаний; взрыв: спасбросок Ловкости', damage='Взрывная руна: 5к8 выбранного типа — кислота, холод, огонь, электричество или звук; половина при успехе', effect_summary='Наносишь почти незаметную руну на поверхность или внутрь закрываемого объекта и задаёшь условие срабатывания. Можно выбрать взрывную руну или сохранить в ней подготовленное заклинание 3 уровня или ниже, которое сработает при активации.', upcast='Взрыв: +1к8 за каждый уровень ячейки выше 3. Руна заклинания может хранить заклинание уровнем не выше использованной ячейки Охранной руны.', notes='Материал расходуется. Если поверхность или объект переместить более чем на 10 футов от места наложения, руна ломается без срабатывания. Сохранённое заклинание с концентрацией действует полную длительность без необходимости поддерживать концентрацию.', author_description='Двести золотых превращаются в магическую записку «не трогать», которая при непослушании взрывается или выпускает заранее приготовленное заклинание. Очень дорогая, но убедительная канцелярия.', author_comment='Если плут говорит «я аккуратно проверю сундук», напомни ему цену алмазной пыли. Пусть знает, сколько стоила его ошибка.' where slug='glyph-of-warding';
update public.spell_catalog set name_ru='Ускорение', casting_time='Действие', spell_range='30 футов', area='1 видимое добровольное существо', duration='Концентрация, до 1 минуты', components=array['В','С','М'], material='стружка корня солодки', check_type='', damage='', effect_summary='Скорость цели удваивается, КД повышается на 2, спасброски Ловкости совершаются с преимуществом. Каждый ход цель получает дополнительное действие, которое можно потратить только на одну атаку, Рывок, Отход, Засаду или Использование.', upcast='', notes='Когда эффект заканчивается, цель до конца своего следующего хода Недееспособна и имеет Скорость 0.', author_description='Делаешь союзника вдвое быстрее, труднее для попадания и даёшь ему ещё одно действие. А потом магия выставляет счёт и на один ход превращает героя в мебель.', author_comment='Ускорение прекрасно ровно до момента, когда концентрация падает посреди драки. Тогда начинается образовательная часть.' where slug='haste';
update public.spell_catalog set name_ru='Гипнотический узор', casting_time='Действие', spell_range='120 футов', area='Куб 30 футов', duration='Концентрация, до 1 минуты', components=array['С','М'], material='щепотка конфетти', check_type='Спасбросок Мудрости', damage='', effect_summary='На мгновение создаёшь цветной узор. Каждое существо в кубе, которое его видит, при провале становится Очарованным. Пока очаровано этим эффектом, оно Недееспособно и имеет Скорость 0.', upcast='', notes='Для конкретной цели эффект заканчивается, если она получает любой урон или другое существо тратит действие, чтобы встряхнуть её.', author_description='Щепотка конфетти — и половина комнаты перестаёт участвовать в реальности. Барды годами тренировались ради эффекта, который ярмарочный мусор делает за одно действие.', author_comment='Если союзник будит загипнотизированного врага уроном в 1 единицу, запомни его имя. Это будущая причина смерти всей группы.' where slug='hypnotic-pattern';
update public.spell_catalog set name_ru='Молния', casting_time='Действие', spell_range='На себя', area='Линия 100 × 5 футов', duration='Мгновенно', components=array['В','С','М'], material='кусочек меха и кристаллический стержень', check_type='Спасбросок Ловкости', damage='8к6 электричеством; половина при успехе', effect_summary='Из тебя вырывается линия молнии длиной 100 и шириной 5 футов. Все существа в линии делают спасбросок Ловкости.', upcast='+1к6 урона за каждый уровень ячейки выше 3.', notes='Линия начинается от тебя и идёт в выбранном направлении.', author_description='Огненный шар для тех, кто умеет выстраивать врагов в очередь. Всё тот же академический подход: восемь к6 и уверенность, что геометрия решит моральные вопросы.', author_comment='Если союзник стоит в линии, это уже не дружеский огонь. Это чертёж.' where slug='lightning-bolt';
update public.spell_catalog set name_ru='Магический круг', casting_time='Действие', spell_range='10 футов', area='Цилиндр радиусом 10 и высотой 20 футов', duration='1 час', components=array['В','С','М'], material='соль и серебряный порошок стоимостью 100+ зм, расходуются', check_type='Телепортация или межпланарный вход внутрь: спасбросок Харизмы', damage='', effect_summary='Создаёшь круг против выбранных типов: Небожителей, Элементалей, Фей, Исчадий и/или Нежити. Они не могут добровольно войти немагически; атаки по целям внутри совершают с помехой; не могут вселяться в существ внутри или накладывать на них Очарование/Испуг. Можно инвертировать круг, удерживая выбранных существ внутри и защищая тех, кто снаружи.', upcast='+1 час длительности за каждый уровень ячейки выше 3.', notes='Материал расходуется. При попытке войти телепортацией или межпланарным перемещением требуется спасбросок Харизмы.', author_description='Сто золотых серебра и соли, чтобы нарисовать границу, которую демоны внезапно начинают уважать. Хотелось бы такой же вариант для плутов и чужих карманов.', author_comment='Если существо из Бездны остановилось перед линией соли, не смей первым проверять, насколько строго оно читает правила.' where slug='magic-circle';
update public.spell_catalog set name_ru='Большой образ', casting_time='Действие', spell_range='120 футов', area='Иллюзия до куба 20 футов', duration='Концентрация, до 10 минут', components=array['В','С','М'], material='кусочек шерсти', check_type='Распознавание: Интеллект (Расследование) против Сл спасброска заклинаний', damage='', effect_summary='Создаёшь убедительный образ объекта, существа или явления размером до куба 20 футов со звуками, запахами и подходящей температурой. Он не наносит урон и не накладывает состояния. Действием Магии можно перемещать иллюзию в пределах дистанции и естественно менять её внешний вид и звуки.', upcast='Ячейка 4+ уровня: длится до рассеивания и не требует концентрации.', notes='Физическое взаимодействие выдаёт иллюзию. После успешного Изучения существо видит сквозь образ, а прочие ощущения становятся для него слабыми.', author_description='Создаёшь двадцатифутовую ложь со звуком, запахом и температурой. Жрецы обычно добиваются меньшего одним только голосом.', author_comment='Если иллюзия убедительнее вашего плана, возможно, именно она должна быть лидером группы.' where slug='major-image';
update public.spell_catalog set name_ru='Массовое лечащее слово', casting_time='Бонусное действие', spell_range='60 футов', area='До 6 видимых существ', duration='Мгновенно', components=array['В'], material=null, check_type='', damage='Лечение: 2к4 + модификатор характеристики заклинаний каждой цели', effect_summary='До шести выбранных видимых существ восстанавливают 2к4 + модификатор характеристики заклинаний HP.', upcast='+1к4 лечения за каждый уровень ячейки выше 3.', notes='Бонусное действие. Не требует концентрации.', author_description='Жрец говорит одно слово, и сразу шестеро перестают умирать так быстро. Очень эффективный способ испортить мне аргумент про бесполезность жрецов.', author_comment='Шесть человек поднялись после одного слова. Теперь жрец уверен, что остальные его слова тоже кому-то нужны.' where slug='mass-healing-word';
update public.spell_catalog set name_ru='Слияние с камнем', casting_time='Действие', spell_range='Касание', area='Каменный объект или поверхность, достаточно большая для твоего тела', duration='8 часов', components=array['В','С'], material=null, check_type='', damage='Частичное разрушение/деформация: 6к6 силового; полное разрушение или превращение камня: 50 силового', effect_summary='Входишь телом и снаряжением в достаточно большой камень и полностью сливаешься с ним. Снаружи не обнаруживаешься немагическими чувствами. Внутри не видишь наружу, слуховые проверки Восприятия идут с помехой, двигаться нельзя; можно накладывать заклинания только на себя. Выход требует 5 футов движения через точку входа.', upcast='', notes='Ритуал. При частичном разрушении или сильной деформации камень выталкивает тебя, наносит 6к6 и роняет Сбитым с ног. Полное разрушение/превращение наносит 50 силового.', author_description='На восемь часов буквально становишься частью стены. Друиды называют это единением с природой. Я называю это самым дорогим способом избежать разговора.', author_comment='Если стену начинают ломать, внезапно понимаешь, почему недвижимость считается рискованной инвестицией.' where slug='meld-into-stone';
update public.spell_catalog set name_ru='Необнаружимость', casting_time='Действие', spell_range='Касание', area='1 добровольное существо, место или объект до 10 футов по любому измерению', duration='8 часов', components=array['В','С','М'], material='щепотка алмазной пыли стоимостью 25+ зм, расходуется', check_type='', damage='', effect_summary='На 8 часов скрывает цель от заклинаний Прорицания. На неё нельзя нацеливаться такими заклинаниями и её нельзя воспринимать через магические сенсоры наблюдения.', upcast='', notes='Материал расходуется. Для существа требуется добровольность.', author_description='Платишь алмазами за восемь часов права не участвовать в чужом магическом любопытстве. Иногда приватность действительно стоит денег.', author_comment='Особенно полезно, если волшебник в группе сказал: «Мне просто интересно, что ты скрываешь».' where slug='nondetection';
update public.spell_catalog set name_ru='Призрачный скакун', casting_time='Действие', spell_range='30 футов', area='1 свободное место на земле', duration='1 час', components=array['В','С'], material=null, check_type='', damage='', effect_summary='Создаёшь Большого квазиреального скакуна с седлом, удилами и уздечкой. Он использует характеристики ездовой лошади, но имеет Скорость 100 футов и проходит 13 миль за час. Ездить может назначенное тобой существо.', upcast='', notes='Ритуал. Заканчивается раньше, если скакун получает любой урон. После окончания он исчезает постепенно, давая всаднику 1 минуту спешиться. Созданная экипировка исчезает, если отнести её дальше 10 футов от скакуна.', author_description='Сто футов скорости, тринадцать миль в час и ни одного настоящего коня, который мог бы возразить против вашего маршрута. Волшебник наконец улучшил транспорт.', author_comment='Получает один урон и исчезает. По крайней мере теперь у коня есть официальный повод бросить партию.' where slug='phantom-steed';
update public.spell_catalog set name_ru='Рост растений', casting_time='Действие', spell_range='150 футов', area='Зарастание: сфера радиусом 100 футов; обогащение: радиус полмили', duration='Мгновенно; обогащение действует 365 дней', components=array['В','С'], material=null, check_type='', damage='', effect_summary='Выбираешь эффект по времени наложения. Зарастание делает обычные растения в сфере радиусом 100 футов густыми: движение там стоит 4 фута за каждый 1 фут; можно исключить любые участки. Обогащение улучшает все растения в радиусе полмили на 365 дней, удваивая урожай.', upcast='', notes='Для эффекта обогащения одно и то же растение получает пользу только от одного такого заклинания в год.', author_description='Либо превращаешь поле в кошмар для передвижения, либо удваиваешь урожай на год. Друид способен решить проблему голода и тут же создать новую проблему с дорогой.', author_comment='Редкое заклинание, после которого крестьяне действительно рады видеть приключенца. Не привыкайте.' where slug='plant-growth';
update public.spell_catalog set name_ru='Защита от энергии', casting_time='Действие', spell_range='Касание', area='1 добровольное существо', duration='Концентрация, до 1 часа', components=array['В','С'], material=null, check_type='', damage='Сопротивление выбранному типу: кислота, холод, огонь, электричество или звук', effect_summary='Цель получает сопротивление одному выбранному типу урона: кислоте, холоду, огню, электричеству или звуку.', upcast='', notes='Тип выбирается при наложении.', author_description='Выбираешь один вид энергии и на час делаешь его вдвое менее убедительным. Очень полезно, особенно если волшебник только что спросил, кто умеет сопротивляться огню.', author_comment='Если перед боем тебе внезапно предлагают защиту от огня, не спрашивай. Просто отойди от волшебника.' where slug='protection-from-energy';
update public.spell_catalog set name_ru='Снятие проклятия', casting_time='Действие', spell_range='Касание', area='1 существо или объект', duration='Мгновенно', components=array['В','С'], material=null, check_type='', damage='', effect_summary='Заканчивает все проклятия на существе или объекте. Если проклят магический предмет, само проклятие предмета остаётся, но связь владельца с ним через Настройку разрывается, позволяя снять или выбросить предмет.', upcast='', notes='Не уничтожает проклятие магического предмета — только прекращает его влияние через Настройку владельца.', author_description='Убирает проклятия одним касанием. Иногда вся сложная история о древнем зле заканчивается потому, что кто-то всё-таки подготовил правильное заклинание.', author_comment='Проклятый меч всё ещё проклят. Зато теперь его можно отдать плуту. Проблема решена административно.' where slug='remove-curse';
